/**
 * The French half of every served tool description (mcp-standard C-19, task
 * k17adhp6pnh5sg64thkqjrn76x8hwwqz). A tool description is served as
 * "<English> / <French>" in its one `description` field. The English text is
 * the one each `defineTool(...)` call declares, unchanged; the French text is
 * read from this map. `composeServedDescription` below is the only place the
 * two are joined, and `defineTool` (registerTool.ts) is its only caller.
 *
 * Each entry is a translation of that tool's declared English description,
 * with the same facts and the same Returns clause. Tool names, field names,
 * error codes, quoted server strings and example arguments stay as they are.
 * The key set is the set of served tools: test/c19-bilingual-descriptions.test.ts
 * fails on a served tool with no entry and on an entry naming no served tool.
 */

/**
 * French counterpart of NO_PERSON_DOOR_NOTE (registerTool.ts), appended to the
 * French half exactly when the English half carries that note.
 */
export const NO_PERSON_DOOR_NOTE_FR =
	" Une personne connectée sans agent est refusée ici (PERSON_NO_HUMAN_DOOR) : reconnectez-vous et choisissez un agent sur la page de consentement.";

/** Separator between the two halves: the shape mcp-doctor C-19 reads. */
export const BILINGUAL_SEPARATOR = " / ";

/**
 * Claude Code truncates a metadata field past 2048 UTF-8 bytes; the guard is
 * test/server-metadata-byte-budget.test.ts. A bilingual description over this
 * budget is not served: the English alone is, unchanged, and the C-19 suite
 * names every tool in that case, so none is monolingual silently.
 */
export const METADATA_FIELD_BUDGET_BYTES = 2048;

/** French description per served tool name. */
export const TOOL_DESCRIPTIONS_FR: Readonly<Record<string, string>> = {
	add_fix_attempt:
		"Enregistre une tentative de correction d'un fix pattern connu : ce qui a été essayé, si cela a fonctionné, pourquoi, et éventuellement son commit. Renvoie { attemptId, patternId, worked }. QUAND : après chaque tentative de correction (réussie ou non), pour constituer un historique complet des corrections. EXEMPLE : add_fix_attempt patternId='j57aaaaa...' description='Added suppressHydrationWarning' worked=true why='Prevents mismatches' createdBy='beta'.",
	add_repo_mapping:
		"Enregistre ou met à jour l'association d'un dépôt GitHub à un orchestrateur, pour le routage des événements webhook. Renvoie { id, repo, orchestrator, project, active, reviewer, fallbackReviewer } ; un nouvel appel pour le même dépôt met l'association à jour. QUAND : à l'ajout d'un nouveau dépôt à la surveillance, ou pour changer l'orchestrateur qui traite ses événements. EXEMPLE : add_repo_mapping repo='vantageos-agency/vantage-peers' orchestrator='alpha' project='vantage-peers'.",
	add_task_dependency:
		"Ajoute des ID de tâches dont une tâche dépend, pour qu'elle ne puisse pas démarrer avant que toutes les tâches listées soient terminées. AJOUTE : les nouveaux ID sont fusionnés dans le dependsOn existant de la tâche (dédoublonnés, les existants d'abord) et la liste complète résultante est renvoyée ; rien de ce qui s'y trouvait n'est retiré. Chaque ID doit être une tâche existante de la même organisation ; une auto-dépendance ou un cycle est refusé. Pour REMPLACER toute la liste, utilisez update_task dependsOn. Renvoie { taskId, dependsOn, updated: true } avec la liste complète résultante. QUAND : à la création d'une tâche qui dépend d'un travail préalable pas encore inscrit dans dependsOn. EXEMPLE : add_task_dependency taskId='k178d3ns...' dependsOn=['k17bbbbb...'] callerOrchestrator='alpha'.",
	billing_summary_by_project:
		"Base de facturation/refacturation : additionne les actualMinutes dérivées par la MACHINE (startedAt→completedAt, jamais une ligne de temps saisie à la main), regroupées par projet, pour les tâches terminées dans [from, to]. QUAND : pour constituer la base de refacturation d'un client ou d'une période, ou pour auditer le temps facturé avant d'émettre une facture. project est facultatif : omettez-le pour obtenir tous les projets, ou passez-en un pour limiter les lignes renvoyées à un seul projet. from/to bornent le moment de clôture des tâches comptées : omettez les deux pour compter toutes les tâches terminées jusqu'à maintenant. Ne masque JAMAIS une troncature : si le parcours sous-jacent a atteint son plafond, `truncated: true` est renvoyé ; traitez-le comme le signal de réduire la période et de relancer la requête, pas comme un total complet. EXEMPLE : billing_summary_by_project project='vantage-immo' from=1783000000000 to=1783949200149. unattributedTaskCount se décompose en noProjectCount (tâche terminée sans projet, quelle que soit sa durée) et noDurationCount (un projet mais aucune durée mesurée) ; une tâche qui n'a ni l'un ni l'autre ne compte que dans noProjectCount. Passez listNoDuration=true pour obtenir aussi noDurationTasks [{taskId, assignedTo, project, completedAt}] (200 au plus ; noDurationTasksTruncated indique quand la liste est coupée). Une durée n'est jamais estimée. Renvoie { byProject: [{project, totalMinutes, taskCount, legacyTaskCount, legacyMinutes}], unattributedTaskCount, noProjectCount, noDurationCount, noDurationTasks?[{ taskId, assignedTo, project, completedAt }], noDurationTasksTruncated?, invalidDurationTaskCount, truncated } : legacyMinutes est la part de totalMinutes chronométrée du début à la clôture plutôt que par segments de travail, invalidDurationTaskCount les tâches terminées écartées pour une durée négative.",
	block_task:
		"Marque une tâche comme bloquée, avec une raison et des ID de tâches bloquantes facultatifs, en passant son statut à blocked. Renvoie { taskId, status: 'blocked', reason, blockedOnTaskId, blockedCause, dependsOn? } ; dependsOn est la liste complète résultante et n'apparaît que si blockedBy a été donné. QUAND : quand une dépendance externe ou une information manquante empêche d'avancer ; consignez le blocage précis. Un blocage est un engagement, pas une simple entrée de journal : citez blockedOnTaskId (une tâche vivante détenue par quelqu'un d'autre) pour que le répondant soit chargé de vous débloquer, OU marquez la raison avec '# blocked-on-nobody: <reason>' quand personne dans la flotte ne détient l'obstacle. Passez blockedCause pour dire CE QUE vous attendez ('human' : une décision ou réponse d'un opérateur ; 'authorisation' : une barrière de merge/publication/approbation ; 'peer_task' : une simple dépendance amont ; 'other' si aucun ne s'applique), afin que l'état d'attente soit dérivable et jamais deviné à partir d'un texte libre. EXEMPLE : block_task taskId='k178d3ns...' blockedOnTaskId='k17bbbbb...' blockedCause='authorisation' reason='Waiting for B2 PR#667 merge' callerOrchestrator='beta'.",
	bulk_complete_tasks:
		"Clôt en masse les tâches ouvertes correspondant à un filtre, en une seule mutation atomique. SÉCURITÉ : un appel sans dryRun ne fait que prévisualiser les tâches correspondantes ; dryRun=false applique. Le filtre doit restreindre (autoGeneratedOnly, assignedTo ou status) ; un filtre vide lève BULK_FILTER_TOO_BROAD. Une exécution réelle exige callerOrchestrator (BULK_CALLER_REQUIRED). 500 tâches au plus sont closes par appel : quand davantage correspondent, l'appel réel en clôt 500, renvoie remaining: true + cappedAt: 500, et le reste s'écoule en arrière-plan sous le même filtre et les mêmes contrôles ; interrogez get_bulk_complete_run avec le bulkRunId. Rappeler avec le même filtre est sans risque : les tâches closes sortent du parcours. Renvoie {count, sampleIds, bulkRunId, executedAt?, cappedAt?, remaining?} : bulkRunId est le jeton de preuve ; cappedAt + remaining apparaissent ensemble quand plus de 500 correspondaient, sinon count est exact. QUAND : nettoyage du spam cron des tâches de sondage check-messages générées automatiquement. EXEMPLE (prévisualisation) : bulk_complete_tasks filter={autoGeneratedOnly:true} callerOrchestrator='system'. EXEMPLE (application) : bulk_complete_tasks filter={status:'todo'} dryRun=false callerOrchestrator='system'.",
	check_messages:
		"Consulte les messages non lus adressés à un rôle destinataire, en renvoyant des receiptIds pour l'accusé de lecture. Renvoie { messages[{ receiptId, from, fromInstanceId?, fromId?, channel?, content, createdAt }], truncated, nextSince, stuckInProgress { entries, total, truncated, actionableStuckCount }, peersStuckOnYou { entries, total, truncated, actionableStuckCount } } ; le texte est la liste des messages en tableau JSON (passez les receiptIds à mark_as_read), ou 'No new messages.' ; une page tronquée se termine par la valeur since= pour reprendre, et les blocs stuckInProgress / peersStuckOnYou suivent quand ils sont présents. QUAND : en début de session et après de longues pauses, pour vider la boîte de réception avant de commencer le travail. EXEMPLE : check_messages recipient='gamma' recipientInstanceId='gamma-vps'.",
	checkout_task:
		"Réserve atomiquement une tâche todo, ce qui évite les situations de concurrence quand plusieurs orchestrateurs se la disputent. Renvoie { claimed: true, reason? } quand la réservation réussit, ou { claimed: false, reason } quand la tâche n'est pas réservable (pas todo, en pause, ou portant un segment de travail ouvert) ; rien n'est alors écrit. QUAND : avant start_task, dans les files à plusieurs orchestrateurs, pour garantir une propriété exclusive. EXEMPLE : checkout_task taskId='k178d3ns...' callerOrchestrator='alpha' callerInstance='alpha-vps'.",
	claim_upload:
		"Réserve un blob téléversé pour votre organisation avec le ticket à usage unique renvoyé par generate_upload_url. QUAND : après l'envoi (POST) d'un fichier à l'URL de téléversement, avant que store_document_chunked l'ingère ou que validate_okf_bundle le lise par storageId. Lie le storageId à votre organisation uniquement si le ticket est valide, inutilisé, non expiré, émis pour votre propre organisation, si le blob a été téléversé après l'émission du ticket et si son contenu correspond au sha256 déclaré à generate_upload_url ; le ticket est consommé. Un storageId sans son ticket ne peut pas être réservé. Renvoie { storageId, orgId }. EXEMPLE : claim_upload storageId='kg2anjqa…' ticket='9f3c…'.",
	complete_task:
		"Marque une tâche comme terminée avec un completionNote obligatoire ; prévenez toujours ensuite le créateur via send_message. Renvoie { taskId, status: 'done' }. QUAND : une fois tous les livrables commités ou vérifiés ; ne terminez jamais sans un jeton de preuve dans la note. EXEMPLE : complete_task taskId='k178d3ns...' completionNote='PR #667 merged, 86 descriptions updated' callerOrchestrator='beta'.",
	correct_task_segment:
		"Rétablit les bornes réelles d'UN segment de travail enregistré, lorsqu'il s'est étendu au-delà d'une pause non enregistrée (par exemple, la session d'une station s'est terminée sans pause_task et le segment est resté ouvert pendant des jours). L'intervalle d'origine enregistré par la machine est conservé, jamais écrasé : le segment corrigé stocke les bornes d'origine, la raison et l'auteur de la correction, et get_task les affiche dans workSegments. Une correction ne peut que RÉDUIRE un intervalle pour qu'il tienne dans ce que la machine a enregistré ; elle ne peut jamais l'étendre ni le déplacer hors de cet intervalle, et le plafond configuré de durée de segment s'applique toujours. Une correction par segment. Renvoie { taskId, segmentIndex, corrected: true }. QUAND : quand complete_task/pause_task refusent une tâche parce que son dernier segment couvre une durée invraisemblable et que le marqueur d'attestation de dépassement de plafond ne convient pas (l'intervalle dépasse 2 fois le plafond, ou le segment est encore ouvert) ; corrigez d'abord le segment, puis appelez complete_task ou pause_task normalement. EXEMPLE : correct_task_segment taskId='k178d3ns...' segmentIndex=0 start=1767250800000 end=1767268800000 reason='unrecorded break, real work was 5 hours' callerOrchestrator='gamma'.",
	create_briefing_note:
		"Crée une note de briefing qui consigne une discussion : son titre, son sujet, ses participants, son contenu complet, les décisions prises et les mémoires sur lesquelles elle s'appuie. Renvoie { noteId, title, topic, createdBy }. QUAND : après des discussions importantes d'architecture, de produit ou d'exploitation, pour consigner durablement les décisions. EXEMPLE : create_briefing_note title='C3 desc standard' topic='architecture' participants=['alpha','beta'] content='...' createdBy='gamma'.",
	create_fix_pattern:
		"Crée un fix pattern dans la base de connaissances, qui documente le symptôme, la cause racine et éventuellement la correction validée. Renvoie { patternId, created: true }. QUAND : après la résolution d'un bug non trivial, pour que les futurs agents puissent retrouver et réutiliser la solution. EXEMPLE : create_fix_pattern symptom='hydration mismatch' rootCause='SSR/CSR time skew' tags=['next.js'] stack=['next.js','convex'] sourceProject='vantage-starter' createdBy='alpha' severity='major'.",
	create_mission:
		"Crée une mission qui regroupe des tâches liées sous un projet, avec un orchestrateur pilote et une liste d'agents. Renvoie { missionId, name, project, pilot, status } ; passez missionId à create_task ou à instantiate_template_into_mission. QUAND : au lancement d'une initiative à plusieurs tâches qui demande un suivi de cycle de vie et un rapport d'avancement. EXEMPLE : create_mission name='Day 92 C3' project='vantage-peers' pilot='alpha' agents=['beta','gamma'] priority='high' createdBy='alpha'.",
	create_recurring_task:
		"Crée un modèle de tâche récurrente qui génère automatiquement des tâches selon une planification cron. Renvoie { taskId, cronExpression } : taskId est l'ID du nouveau modèle (le recurringTaskId que prennent les autres outils de tâches récurrentes). QUAND : pour les points quotidiens, les revues hebdomadaires ou tout travail qui se répète. EXEMPLE : create_recurring_task title='Daily standup' assignedTo='alpha' priority='medium' cronExpression='0 9 * * *' createdBy='alpha'.",
	create_task:
		"Crée une tâche assignée à un orchestrateur, avec priorité, suivi de statut et lien facultatif vers une mission. Renvoie { taskId, title, assignedTo, priority, status } ; conservez taskId pour start_task, update_task et complete_task. QUAND : pour déléguer du travail, suivre un livrable ou instancier une étape d'un plan de mission. `project` est obligatoire : une tâche sans projet est refusée, car la facturation regroupe les tâches terminées par projet. EXEMPLE : create_task title='Standardize tool descriptions' project='vantage-peers' assignedTo='beta' priority='high' createdBy='alpha'.",
	debate_get_room:
		"Lit une salle de débat : son sujet, son modèle figé, son pointeur et la transcription complète. Lecture seule. Renvoie { room { _id, _creationTime, tenantId, tenantOrgId, templateId, template, settings, subject, status, round, position, turnSeq, participantState, createdBy, createdById, createdAt, refusalRows, refusalsOverflow }, turns[{ _id, _creationTime, roomId, turnSeq, round, position, kind, writer, postedAt }], truncated? } : la salle (sujet, modèle figé, statut, à qui c'est le tour) et chaque tour dans l'ordre ; une salle dont vous ne faites pas partie renvoie une erreur ROOM NOT AVAILABLE, jamais une salle vide. Au-delà du plafond de réponse de 60 Ko, la transcription est coupée à ses premiers tours et le signale (truncated: true, et _meta dans le texte). QUAND : le message [DEBATE-TURN] indique que des tours précédents ont été omis, ou vous avez besoin de toute la transcription. EXEMPLE : debate_get_room roomId='<roomId from the message>'.",
	debate_post_turn:
		"Publie votre réponse au tour de salle de débat qui vous a été demandé ; c'est le seul moyen pour un tour d'entrer dans une salle. Renvoie { accepted: true, turnSeq, closed, closeReason?, workDuringTurn } quand le tour est enregistré. QUAND : le message [DEBATE-TURN] de votre boîte de réception le demande, une seule fois par turnSeq, puis marquez ce message comme lu. EXEMPLE : debate_post_turn roomId='<roomId from the message>' turnSeq=3 text='...' done=false. Un refus (not_your_turn, stale_turn, too_long, room_closed, ...) est renvoyé comme résultat d'erreur, jamais comme un succès.",
	delete_message:
		"Supprime un message et tous ses accusés de réception ; seul l'expéditeur d'origine ou system peut supprimer. Renvoie { deleted: true, receiptsDeleted }. QUAND : pour retirer une diffusion erronée ou un contenu sensible avant que les destinataires le lisent. EXEMPLE : delete_message messageId='j57dy3049btafda9m2f5d2ggk987ph3f' callerOrchestrator='alpha'.",
	delete_recurring_task:
		"Supprime définitivement un modèle de tâche récurrente, ce qui arrête toute génération planifiée de tâches à venir. Renvoie { deleted: true }. QUAND : quand un processus récurrent est retiré et ne doit plus jamais générer de tâches. EXEMPLE : delete_recurring_task taskId='j57aaaaa...'.",
	delete_task:
		"Supprime définitivement une tâche ; seul le créateur ou le rôle system peut supprimer. Renvoie { deleted: true }. QUAND : pour retirer des tâches créées par erreur ou des artefacts de test ; préférez complete_task pour un vrai travail. EXEMPLE : delete_task taskId='k178d3ns...' callerOrchestrator='alpha'.",
	erase_fix_pattern:
		"Efface définitivement un fix pattern : le pattern, ses tentatives de correction et son entrée de recherche sont SUPPRIMÉS. Renvoie { patternId, erased: true, cascaded }, où cascaded compte les lignes dépendantes supprimées avec lui (fixAttempts, searchEntry). QUAND : un fix pattern a été enregistré par erreur, ou porte un contenu qui doit disparaître pour de bon. Autorisé pour un administrateur de l'organisation opératrice uniquement (un fix pattern ne porte aucun auteur, pas plus qu'une ligne d'issue) ; un agent qui n'est pas administrateur, toute organisation cliente et un appel du fleet master sans preuve sont refusés avec RBAC_DENIED, et le pattern reste inchangé. EXEMPLE : erase_fix_pattern patternId='m9748paffd0emrbwyskj868e1x88kvhj'.",
	erase_memory:
		"Efface définitivement un secret (un identifiant, un jeton ou une clé) d'une mémoire : le texte correspondant est remplacé dans le corps stocké, l'empreinte du contenu est recalculée et l'entrée de l'index de recherche est réindexée et purgée, si bien que le texte d'origine disparaît (contrairement à soft_delete_memory, qui laisse le corps lisible). Renvoie { memoryId, replacements, contentHashChanged } ; un texte find qui n'apparaît nulle part est refusé (REDACT_NO_MATCH), jamais ignoré en silence. QUAND : un identifiant a été collé dans une mémoire et ne doit pas rester récupérable. Autorisé pour un administrateur de l'organisation (toute mémoire de l'organisation), pour la personne qui a rédigé la mémoire, ou pour l'agent (siège) dont l'ID vérifié l'a rédigée ; toute autre personne est refusée avec RBAC_DENIED. EXEMPLE : erase_memory memoryId='j57dy3049btafda9m2f5d2ggk987ph3f' redactions=[{find:'sk-live-abc', replaceWith:'[REDACTED]'}].",
	erase_row:
		"Efface définitivement une ligne que vous ou votre organisation détenez : la ligne est SUPPRIMÉE (et, pour une mémoire, son entrée de recherche est purgée), contrairement aux suppressions logiques qui laissent le corps lisible. Tables couvertes : memories, messages, missions, tasks, recurringTasks, briefingNotes, diary, debateRooms, issues, businessUnits, debateTemplates. Renvoie { table, rowId, erased: true, cascaded }, où cascaded compte les lignes dépendantes supprimées avec elle (accusés de réception, tours, participants). QUAND : un contenu rédigé doit disparaître pour de bon. Autorisé pour un administrateur de l'organisation (toute ligne de l'organisation), pour la personne qui a écrit la ligne, ou pour l'agent (siège) dont l'ID vérifié l'a écrite ; une ligne sans ID d'auteur stocké (ancienne, ou écrite par un siège non vérifié) ne peut être effacée que par un administrateur ; toute autre personne, et toute autre organisation, est refusée avec RBAC_DENIED et la ligne reste inchangée. Pour un secret contenu dans une mémoire qui doit par ailleurs être conservée, utilisez erase_memory. EXEMPLE : erase_row table='tasks' rowId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	export_okf_bundle:
		"Exporte un namespace VantagePeers sous forme de bundle OKF v0.1 (archive tar). Renvoie { bundleUrl, storageId, size, fileCount, manifest: { types: { memoryCount, briefingCount, taskCount }, truncated, urlExpiresAt } } ; le bundleUrl signé cesse de fonctionner à urlExpiresAt, quand le bundle stocké est purgé. QUAND : pour envoyer un instantané vers Knowledge Catalog, un pont RAG ou un audit. EXEMPLE : export_okf_bundle namespace='project/elpi-corp' format='tarball'.",
	fail_task:
		"Marque une tâche comme échouée (un état terminal distinct de done/cancelled) avec un failureNote obligatoire décrivant comment le travail s'est terminé. Renvoie { taskId, status: 'failed' }. QUAND : quand le travail a réellement été tenté et n'a pas abouti ; n'appelez jamais complete_task pour clore un travail échoué, et n'appelez jamais update_task avec status=\"failed\" (refusé côté serveur ; cet outil est la seule porte). Une tâche déjà done/cancelled ne peut pas être reterminée en failed. EXEMPLE : fail_task taskId='k178d3ns...' failureNote='Migration errored on row 4102, rolled back cleanly' callerOrchestrator='beta'.",
	generate_upload_url:
		"Génère une URL de téléversement de stockage Convex pour le flux d'ingestion de la base de connaissances. L'organisation de l'appelant (issue du JWT Clerk) est liée implicitement. Pour RÉSERVER le téléversement ensuite (obligatoire avant que validate_okf_bundle le lise), calculez d'abord le SHA-256 du fichier exact que vous allez téléverser et passez-le en sha256 : la réponse porte alors aussi un ticket de téléversement à usage unique, lié à votre organisation ET à ce contenu (valable 15 minutes, affiché une seule fois) ; après le POST, appelez claim_upload avec le storageId et le ticket. Sans sha256, vous n'obtenez que l'URL (pas de ticket) : ce blob ne peut pas être réservé, donc store_document_chunked le refuse. Passez sha256 pour tout téléversement que vous comptez ingérer. Exige un JWT Clerk avec org_id ; les porteurs sans organisation sont rejetés. Une URL par appel. Renvoie { uploadUrl, ticket, expiresAt?, note? } ; le texte est l'URL de téléversement seule (premier élément), puis un élément JSON { ticket, expiresAt } (ticket null, avec une note, quand aucun sha256 n'a été passé). EXEMPLE : generate_upload_url sha256='2cf24dba…' → 'https://…convex.cloud/api/storage/upload?...' + {\"ticket\":\"9f…\",\"expiresAt\":…}.",
	get_briefing_note:
		"Récupère une note de briefing par son noteId. Renvoie { _id, _creationTime, title, topic, participants, content, contentTruncated?, decisions?, linkedMemoryIds?, createdBy, createdAt, updatedAt?, updatedBy?, orgId? }, la note stockée. Une note que vous ne pouvez pas lire, ou qui n'existe pas, est un résultat d'erreur ('Briefing note not found'). QUAND : quand vous avez un noteId précis et avez besoin de l'enregistrement structuré complet pour une passation ou un récapitulatif. EXEMPLE : get_briefing_note noteId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	get_bulk_complete_run:
		"Lit le statut d'une exécution réelle de bulk_complete_tasks par le `bulkRunId` que son premier appel a renvoyé. QUAND : un appel bulk_complete_tasks a signalé `remaining: true` ; le reste s'écoule en arrière-plan, et c'est ici que vous voyez comment cela s'est passé. Renvoie {bulkRunId, status, closed, remaining, failureReason?, createdBy, orgId?, startedAt, updatedAt} : status `running` (des lots s'écoulent encore), `complete` (la pile a disparu ; `closed` est le total) ou `failed` (un lot ultérieur a été refusé, par le RBAC ou la barrière de clôture ; `failureReason` dit pourquoi, `closed` est ce qui a été clos avant, le reste demeure ouvert ; rappeler bulk_complete_tasks avec le même filtre rencontre le même refus). Lisible uniquement par l'organisation de l'exécution et par son créateur ; tout autre id, organisation ou appelant obtient 'not found'. EXEMPLE : get_bulk_complete_run bulkRunId='bulk-1760000000000-ab12cd34'.",
	get_diary:
		"Récupère l'entrée de journal d'un orchestrateur pour une date. Renvoie { found, item? { _id, _creationTime, date, orchestrator, content, createdAt }, id? } : item est l'entrée de journal (content, highlights, blockers, createdBy) quand found vaut true, id le '<orchestrator>/<date>' demandé quand found vaut false ; le texte est l'entrée en JSON, ou null quand il n'en existe aucune pour cette date et cet orchestrateur. QUAND : pour revoir ce qu'un orchestrateur a fait un jour donné, pour un récapitulatif ou un briefing de passation. EXEMPLE : get_diary date='2026-06-06' orchestrator='alpha'.",
	get_episode:
		"Récupère un épisode unique par l'ID de son document mémoire. Les épisodes sont des mémoires de type='episode' portant context/goal/action/outcome/insight + severity. Renvoie { _id, _creationTime, namespace, type, content, createdBy, createdById?, instanceId?, relations[{ targetId, type }], isLatest, ttl?, createdAt, updatedAt, contentHash?, clerkOrgId?, episode? { context, goal, action, outcome, insight, severity } }, la ligne mémoire de l'épisode : les champs structurés sont sous episode, l'auteur est createdBy. Un ID qui n'est pas un épisode, ou que vous ne pouvez pas lire, est un résultat d'erreur ('Episode not found'). QUAND : quand vous avez un episodeId issu de store_episode ou d'une recherche précédente et avez besoin de l'enregistrement complet. EXEMPLE : get_episode episodeId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	get_fix_pattern:
		"Récupère un fix pattern unique par son patternId, avec jusqu'à 100 de ses tentatives de correction. Renvoie { _id, _creationTime, symptom, rootCause, validatedFix?, files?, tags, stack, sourceProject, linkedIssueIds?, createdBy, severity, createdAt, updatedAt, attempts[{ _id, description, commit?, worked, why, createdBy, createdAt }] }. Un pattern que vous ne pouvez pas lire est refusé avec RBAC_DENIED, et un pattern qui n'existe pas est un résultat d'erreur ('Fix pattern not found'). QUAND : quand vous avez un patternId issu de list_fix_patterns/search_fix_patterns et avez besoin de l'enregistrement complet avec l'historique des tentatives. EXEMPLE : get_fix_pattern patternId='m9748paffd0emrbwyskj868e1x88kvhj'.",
	get_github_owner_bindings:
		"Liste les propriétaires GitHub liés à votre organisation (master : tous) et, pour le master, les associations de dépôts détenues par une organisation qui n'ont aucune preuve. Renvoie { bindings[{ owner, orgId, installationId, accountType, githubUserLogin, boundAt, active }], nextCursor, unprovenMappings?[{ repo, orgId, project, reason }], unprovenNextCursor? } ; les champs unproven ne sont présents que pour le fleet master, et un curseur null signifie que cette liste est épuisée. QUAND : pour voir quels dépôts vous pouvez associer, ou pour auditer les associations créées sans preuve GitHub. EXEMPLE : get_github_owner_bindings limit=100. Pagination par curseur : renvoyez `nextCursor` en `cursor` (et `unprovenNextCursor` en `unprovenCursor`) ; null signifie épuisé.",
	get_memory:
		"Récupère une mémoire unique par son memoryId, avec ses relations et les métadonnées d'épisode. Renvoie { _id, _creationTime, namespace, type, content, createdBy, createdById?, instanceId?, relations[{ targetId, type }], isLatest, ttl?, createdAt, updatedAt, contentHash?, clerkOrgId?, episode? { context, goal, action, outcome, insight, severity } }, la ligne mémoire : createdBy est l'auteur, episode n'est présent que sur un épisode. Une mémoire que vous ne pouvez pas lire, ou qui n'existe pas, est un résultat d'erreur ('Memory not found'). QUAND : quand vous avez un memoryId précis issu d'un recall/store précédent et avez besoin de l'enregistrement complet. EXEMPLE : get_memory memoryId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	get_message:
		"Récupère un message de pair unique : son corps complet, son expéditeur, son canal, son jour de session et son organisation. Renvoie { _id, _creationTime, from, fromId?, fromInstanceId?, channel, content, sessionDay?, tenantId?, tenantOrgId?, createdAt } : from est l'expéditeur, tenantId l'organisation dans laquelle il a été envoyé. Un message que vous ne pouvez pas lire, ou qui n'existe pas, est un résultat d'erreur ('Message not found'). QUAND : quand vous avez un messageId issu de list_messages/check_messages et avez besoin de la ligne brute (par exemple pour un audit d'accusé de lecture, une confirmation de suppression, ou pour le citer dans un fix pattern). EXEMPLE : get_message messageId='jn7eg21wdaxzdcpdxwkvhaxqnh88jqg2'.",
	get_mission:
		"Récupère une mission unique par son ID avec tous ses détails : statut, pilote, agents, avancement, dates de début et d'échéance. Renvoie { found, item? { _id, _creationTime, name, project, status, priority, pilot, agents, createdBy, createdAt, updatedAt }, id? } : item est le document de mission (status, pilot, agents, progress, startDate, targetDate, brief) quand found vaut true, id le missionId demandé quand found vaut false ; le texte est la mission en JSON, ou null quand elle n'existe pas ou ne vous est pas visible. QUAND : avant d'assigner des tâches ou de faire un rapport, pour obtenir l'état de référence de la mission. EXEMPLE : get_mission missionId='k57a36y8w5t085bqr23dsmvb2d882506'.",
	get_mission_template:
		"Récupère un modèle de mission par son nom, avec toutes ses étapes. Renvoie { found, item? { _id, _creationTime, name, steps, isDefault, createdBy, createdAt, updatedAt }, id? } : item est le modèle (name, description, brief, steps, isDefault) quand found vaut true, id le nom demandé quand found vaut false ; le texte est le modèle en JSON, ou null quand aucun modèle visible ne porte ce nom. QUAND : avant instantiate_template_into_mission, pour inspecter les étapes et vérifier que le modèle existe. EXEMPLE : get_mission_template name='issue-resolution-v2'.",
	get_owner_tool_usage:
		"Liste les outils MCP qu'une personne a utilisés, à travers tous les agents qu'elle détient (un par client IA) et ses propres appels directs, additionnés par outil avec le premier appel le plus ancien et le dernier appel le plus récent. Renvoie { items[{ tool, firstAt, lastAt, count }], truncated? }, additionnés sur les agents de la personne et ses propres appels (horodatages en millisecondes Unix) ; au-delà du plafond de réponse de 60 Ko, les éléments sont coupés et truncated vaut true. Le texte est le même objet en JSON. QUAND : pour savoir ce qu'une étape d'intégration doit encore présenter à une personne, quel que soit le client IA qu'elle a utilisé. EXEMPLE : get_owner_tool_usage ownerUserId='user_2abc' (un administrateur d'organisation qui lit un membre).",
	get_profile:
		"Récupère le profil d'un orchestrateur, avec ses champs d'identité statique et d'état de session dynamique. Renvoie { found, item? { _id, _creationTime, orchestratorId, name, static, dynamic }, id? } : item est le profil (orchestratorId, name, static, dynamic) quand found vaut true, id l'orchestratorId demandé quand found vaut false, ce qui est aussi la réponse quand aucun profil portant cet ID ne vous est visible. Le texte est le même objet en JSON. QUAND : pour vérifier le statut, les capacités ou la tâche en cours d'un pair avant de lui assigner du travail. EXEMPLE : get_profile orchestratorId='gamma'.",
	get_recurring_task:
		"Récupère un modèle de tâche récurrente par son ID. Renvoie { _id, _creationTime, title, description?, assignedTo, assignedToId?, priority, project?, tags?, cronExpression, nextRunAt, lastCreatedAt?, lastTaskId?, skippedRuns?, lastSkippedAt?, lastSkipReason?, active, createdBy, orgId? }, le modèle stocké ; un modèle que vous ne pouvez pas lire, ou qui n'existe pas, est un résultat d'erreur ('Recurring task not found'). lastTaskId est la dernière tâche créée par la planification ; skippedRuns compte les exécutions consécutives qui n'ont rien créé parce que cette tâche était encore ouverte, et se remet à zéro quand une tâche est créée. QUAND : quand vous détenez un recurringTaskId et avez besoin de sa planification, de son assigné et de sa dernière exécution. EXEMPLE : get_recurring_task recurringTaskId='k57dy3049btafda9m2f5d2ggk987ph3f'.",
	get_task:
		"Récupère une tâche par son taskId. Renvoie { _id, _creationTime, title, description?, assignedTo, assignedToId?, priority, status, project?, tags?, dependsOn?, missionId?, completionNote?, completionOutcome?, workSegments?[{ start }], estimatedMinutes?, actualMinutes?, startedAt?, completedAt?, dueDate?, blockedOnTaskId?, blockedCause?, deliverableState? { state, checkedAt }, deliverableDivergence?, createdBy?, createdAt?, updatedAt?, orgId? }, la tâche stockée ; deliverableDivergence est présent quand un livrable publié est encore ouvert. Une tâche que vous ne pouvez pas lire, ou qui n'existe pas, est un résultat d'erreur ('Task not found'). QUAND : quand vous détenez un taskId et avez besoin de l'enregistrement complet : le brief dans description, ses segments de travail et sa note de clôture. EXEMPLE : get_task taskId='k172735brsw6bc3j2dkkkfxqrx88kkjq'.",
	get_tool_usage:
		"Liste les outils MCP qu'un appelant a appelés, avec l'heure du premier appel, l'heure du dernier appel et le nombre d'appels de chacun. Renvoie { items[{ tool, firstAt, lastAt, count }], truncated? }, une ligne par outil appelé par l'appelant (horodatages en millisecondes Unix) ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour voir ce qu'une personne ou un siège d'agent a déjà essayé, par exemple pour savoir ce qu'une étape d'intégration doit encore présenter. EXEMPLE : get_tool_usage (votre propre usage) ou get_tool_usage caller='agent:<agent id>' (un administrateur d'organisation qui lit un siège).",
	hybrid_search:
		"Recherche combinée vectorielle + BM25 par Reciprocal Rank Fusion, pour la meilleure couverture sémantique et par mots-clés. Renvoie { items[{ memoryId, rrfScore, namespace, type, content }], truncated? }, le score fusionné le plus élevé en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : une requête doit correspondre à la fois par le sens et par les termes exacts ; elle fusionne les deux classements que recall et text_search calculent séparément. EXEMPLE : hybrid_search query='onboarding customer flow' namespace='project/vantage-peers' limit=20.",
	import_okf_bundle:
		"Importe un bundle OKF v0.1 (mémoires + notes de briefing + tâches) dans un namespace VantagePeers cible. Renvoie { imported: { memories, briefings, tasks }, skipped, conflicts: [{ path, reason }] } ; en dry-run, les compteurs sont ce qu'une fusion importerait, et rien n'est écrit. Les entrées déjà présentes (même contenu) sont ignorées, si bien qu'une réimportation n'importe rien. QUAND : pour restaurer un instantané, migrer des données d'espace de travail entre tenants, ou rejouer un export. EXEMPLE : import_okf_bundle storageId='abc...' targetNamespace='team/acme-corp' mode='merge'.",
	improvisation_digest:
		"Audite une fenêtre glissante de notes de tâches closes, de messages et de mémoires récents, à la recherche d'affirmations sur l'état de la flotte (un SHA de commit, un numéro de PR, un ID VantagePeers, ou un verbe décisif comme merged, deployed ou approved) qui ne portent aucune ligne de citation de source (un marqueur 'recall(\"<query>\")→[ids]' ou 'none-needed: <reason>'). Servi au fleet master uniquement ; consultatif, il ne modifie ni ne bloque rien. Renvoie { countsByOrch, countsByCategory, samples[{ orchestrator, day, category, snippet, artifactId }] } : countsByOrch associe à chaque orchestrateur son nombre d'artefacts signalés ; countsByCategory les compte par l'outil qui les a écrits (notes complete_task, messages send_message, mémoires store_memory) ; samples liste jusqu'à 50 artefacts signalés, les plus récents d'abord, chacun { orchestrator, day (YYYY-MM-DD), category, snippet (200 premiers caractères), artifactId }. 2000 lignes au plus de chaque sorte sont lues par appel. QUAND : pour auditer une fenêtre de sprint ou le taux de citation d'un orchestrateur. EXEMPLE : improvisation_digest windowDays=7 orchestrators=['sigma','pi'].",
	instantiate_template_into_mission:
		"Crée une tâche par étape de modèle dans une mission, pré-assignée à l'orchestrateur déclaré de chaque étape. Si la mission cible n'a pas encore de brief, le brief propre au modèle (s'il en a un) y est copié ; le brief de la mission, une fois défini, n'est jamais écrasé. Renvoie { taskIds, count } : les ID des tâches créées, dans l'ordre des étapes. QUAND : après create_mission, pour déployer en un seul appel un flux de travail standard à partir d'un modèle. EXEMPLE : instantiate_template_into_mission templateName='issue-resolution-v2' missionId='k57a36y8...' callerOrchestrator='alpha'.",
	link_issue_to_pattern:
		"Lie une issue VantagePeers à un fix pattern en créant une référence bidirectionnelle. Renvoie { patternId, issueId, linked: true } ; lier une issue déjà liée ne change rien. QUAND : après la création d'un fix pattern pour une issue, pour relier l'enregistrement du symptôme au suivi de bugs. EXEMPLE : link_issue_to_pattern patternId='j57aaaaa...' issueId='j57bbbbb...'.",
	list_blocked_on_me:
		"Liste les tâches que d'autres pairs ont BLOQUÉES sur l'une de VOS tâches vivantes (blockedOnTaskId), l'attente la plus ancienne en premier, avec l'âge de chaque attente. Une lecture dédiée, sur demande : check_messages ne renvoie que des messages et ne porte jamais cette liste. QUAND : après check_messages, ou avant de prendre un nouveau travail, pour voir qui vous attend. EXEMPLE : list_blocked_on_me. Renvoie { entries[{ blockedTaskId, blockedTitle, blockedAssignee, onTaskId, onTaskTitle, age }], total, truncated, oldestAge } ; les âges sont en ms. truncated=true signifie que le parcours borné s'est arrêté tôt et que total est une borne inférieure. Une liste vide est une absence réelle ; un refus est une erreur, jamais une liste vide.",
	list_briefing_notes:
		"Liste les notes de briefing filtrées par sujet, les plus récentes d'abord, avec pagination par curseur. Renvoie { items[{ _id, title, topic, participants, createdBy, _creationTime }], nextCursor, truncated } : items sont les notes, les plus récentes d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des notes sur la dernière page, sinon { items, nextCursor }. QUAND : pour revoir les discussions récentes sur un sujet ou auditer tout l'historique des briefings. EXEMPLE : list_briefing_notes topic='architecture' limit=10 fields='lite'.",
	list_broadcast_status:
		"Affiche l'état lu/non lu des accusés de réception d'un message diffusé, par messageId. Renvoie { messageId, from, channel, createdAt, receipts: [{ recipient, recipientInstanceId, read, readAt }], truncated, scopeFiltered? }. QUAND : après send_message, pour confirmer que tous les destinataires ont pris connaissance d'une annonce critique. EXEMPLE : list_broadcast_status messageId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	list_diaries:
		"Liste les entrées de journal filtrées par orchestrateur ou par auteur, les plus récentes d'abord, avec pagination par curseur. Renvoie { items[{ _id, _creationTime, date, orchestrator, content, createdAt }], nextCursor, truncated } : items sont les entrées de journal, les plus récentes d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le même objet en JSON. QUAND : pour revoir l'historique récent sur plusieurs sessions ou auditer une période d'activité. EXEMPLE : list_diaries orchestrator='beta' limit=10.",
	list_episodes:
		"Liste les épisodes (mémoires de type='episode'), les plus récents d'abord. Renvoie { items[{ _id, _creationTime, namespace, type, content, createdBy, relations, isLatest, createdAt, updatedAt }], nextCursor, truncated } : items sont les documents d'épisode, les plus récents d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est la même page en JSON, sans nextCursor sur la dernière page. QUAND : pour énumérer les épisodes par namespace ou par créateur avant un recall ou un audit. EXEMPLE : list_episodes namespace='orchestrator/sigma' limit=20.",
	list_fix_patterns:
		"Liste les fix patterns filtrés par projet source, les plus récents d'abord, avec pagination par curseur. Renvoie { items[{ _id, _creationTime, symptom, rootCause, tags, stack, sourceProject, createdBy, severity, createdAt, updatedAt }], nextCursor, truncated } : items sont les fix patterns, les plus récents d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des patterns sur la dernière page, sinon { items, nextCursor }. QUAND : pour auditer la base de connaissances ou revoir tous les patterns d'un projet donné. EXEMPLE : list_fix_patterns project='vantage-starter' limit=20.",
	list_memories:
		"Liste les mémoires actives (isLatest=true) d'un namespace, les plus récentes d'abord. Renvoie { items[{ _id, _creationTime, namespace, type, content, createdBy, relations, isLatest, createdAt, updatedAt }], nextCursor, truncated } : items sont les documents mémoire (dernières versions uniquement), les plus récents d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est la même page en JSON, sans nextCursor sur la dernière page. QUAND : pour auditer le contenu d'un namespace ou paginer toutes ses entrées sans requête. EXEMPLE : list_memories namespace='project/vantage-peers' type='project' limit=20.",
	list_messages:
		"Liste les messages historiques filtrés par jour de session ou par expéditeur, les plus récents d'abord ; utilisez check_messages pour les non lus. Renvoie { items[{ _id, from, content, createdAt, _creationTime }], nextCursor, truncated } : items sont les messages, les plus récents d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors le curseur qui reprend après la dernière ligne affichée). Le texte est le tableau JSON nu des messages sur la dernière page, sinon { items, nextCursor }. QUAND : pour un audit, un récapitulatif ou le débogage du trafic de messages d'un jour précis. EXEMPLE : list_messages sessionDay=92 from='alpha' limit=20.",
	list_missions:
		"Liste les missions filtrées par projet, pilote ou statut, récentes d'abord, paginées par curseur. Renvoie { items[{ _id, _creationTime, name, status, pilot, priority, project }], nextCursor, truncated } : items, les missions, récentes d'abord ; nextCursor, le curseur de la page suivante, null en dernière page ; truncated vaut true si le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des missions en dernière page, sinon { items, nextCursor }. QUAND : auditer les missions actives, trouver celles d'un pilote ou suivre l'avancement multi-projets. Raccourcis de statut : open = brainstorm, plan, execute et validate ; active = plan et execute ; all = aucun filtre. Un raccourci s'emploie seul : ['open'], jamais ['open', 'execute']. Hors fleet master, l'appelant doit passer pilot égal à son propre ID utilisateur, sinon il est refusé ; seul le fleet master liste tous les pilotes. EXEMPLE : list_missions project='vantage-peers' status=['execute'] pilot='alpha' limit=20.",
	list_peers:
		"Liste tous les profils d'orchestrateurs avec leur tâche en cours et leurs informations de session, les plus récents d'abord. Pour un jeton d'organisation, liste les agents de l'organisation, chacun avec son `agentId` unique : passez-le à send_message `recipientAgentIds` (agentId null = non adressable). Renvoie { items[{ id, instanceId, name, role, workspace, currentTask, lastSeen, sessionCount }], nextCursor, truncated, scopeFiltered? } : items sont les profils, les plus récents d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; scopeFiltered compte les lignes retenues par le périmètre ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des profils, ou { items, nextCursor?, scopeFiltered? } quand une autre page existe ou que des lignes ont été retenues. QUAND : avant d'assigner du travail ou d'envoyer un message direct, pour confirmer qui est actif et ce qu'il fait. EXEMPLE : list_peers limit=20.",
	list_recurring_tasks:
		"Liste les modèles de tâches récurrentes filtrés par assigné ou statut actif, récents d'abord. Renvoie { items[{ _id, _creationTime, title, assignedTo, priority, cronExpression, nextRunAt, active, createdBy }], nextCursor, truncated, scopeFiltered? } : items, les modèles, récents d'abord ; nextCursor, le curseur de la page suivante, null en dernière page ; scopeFiltered, les lignes retenues par le périmètre ; truncated vaut true si le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des modèles, ou { items, nextCursor?, scopeFiltered? } s'il existe une autre page ou des lignes retenues. QUAND : auditer les planifications actives ou trouver des modèles à mettre en pause, reprendre ou modifier. Chaque ligne donne aussi l'état d'instance ouverte unique : lastTaskId (tâche de la dernière exécution), skippedRuns (déclenchements consécutifs sautés car cette tâche était encore ouverte), lastSkippedAt, lastSkipReason. EXEMPLE : list_recurring_tasks assignedTo='beta' active=true limit=20.",
	list_repo_mappings:
		"Liste toutes les associations webhook de dépôt GitHub à orchestrateur, les plus récentes d'abord, avec pagination par curseur. Renvoie { items[{ _id, _creationTime, repo, orchestrator, project }], nextCursor, truncated } : items sont les associations, les plus récentes d'abord ; nextCursor est null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est la même page en JSON. QUAND : pour auditer quels dépôts sont surveillés et vérifier le routage avant d'ajouter de nouvelles associations. EXEMPLE : list_repo_mappings limit=20 fields='lite'.",
	list_tasks:
		"Liste les tâches avec des filtres facultatifs par assigné, statut, projet ou créateur, les plus récentes d'abord. Renvoie { items[{ _id, _creationTime, title, assignedTo, priority, status }], nextCursor, truncated } : items sont les tâches, les plus récentes d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des tâches sur la dernière page, sinon { items, nextCursor }. QUAND : pour consulter le backlog, revoir les éléments en cours ou auditer les tâches d'un projet donné. EXEMPLE : list_tasks assignedTo='gamma' status=['in_progress'] project='vantage-peers' limit=20. excludeAutoGenerated : à true, écarte les tâches créées par cron (createdBy commence par `cron-` OU le titre correspond au motif de sondage `/check-messages`). À utiliser pour garder la file de Pi propre du bruit du planificateur. Avec updatedSince, les lignes arrivent les plus récemment MISES À JOUR d'abord, et une fenêtre de toute taille se pagine en entier via nextCursor. Refusé au-delà de 2000 lignes (retirez une clé, restreignez par statut ou augmentez updatedSince) : assignedTo avec createdBy, project ou assignedToInstance avec createdBy ou updatedSince, et createdBy sur une fenêtre updatedSince où ce créateur est rare. Raccourcis de statut : open vaut todo, in_progress, review et blocked ; active vaut todo et in_progress ; all n'applique aucun filtre. Un raccourci est seul dans la liste de statuts : ['open'], jamais ['open', 'done']. Un appelant autre que le fleet master ne peut nommer dans assignedTo (ou, sans lui, dans createdBy) qu'une identité de son fromAllowList (whoami la liste) ; un autre nom est refusé.",
	list_tasks_by_mission:
		"Liste toutes les tâches liées à une mission, éventuellement filtrées par statut, les plus récentes d'abord. Renvoie { items[{ _id, _creationTime, title, assignedTo, priority, status }], nextCursor, truncated, scopeFiltered? } : items sont les tâches, les plus récentes d'abord ; nextCursor est le curseur de la page suivante, null sur la dernière page ; scopeFiltered compte les lignes retenues par le périmètre ; truncated vaut true quand le plafond de réponse de 60 Ko a coupé la page (nextCursor est alors null). Le texte est le tableau JSON nu des tâches, ou { items, nextCursor?, scopeFiltered? } quand une autre page existe ou que des lignes ont été retenues. QUAND : pour revoir l'avancement d'une mission ou trouver les tâches bloquées/ouvertes d'une mission donnée. Raccourcis de statut : open vaut todo, in_progress, review et blocked ; active vaut todo et in_progress ; all n'applique aucun filtre. Un raccourci est seul dans la liste de statuts : ['open'], jamais ['open', 'done']. EXEMPLE : list_tasks_by_mission missionId='k57a36y8...' status=['in_progress'] limit=20.",
	mark_as_read:
		"Marque un ou plusieurs accusés de réception de messages comme lus, à l'aide des receiptIds issus de check_messages. Renvoie { markedAsRead: <count> } ; un accusé déjà lu n'est pas recompté. QUAND : immédiatement après le traitement de chaque lot de messages renvoyé par check_messages. EXEMPLE : mark_as_read receiptIds=['j57aaaaa...', 'j57bbbbb...'] callerOrchestrator='pi'.",
	pause_recurring_task:
		"Met en pause un modèle de tâche récurrente pour qu'il cesse de créer automatiquement des tâches jusqu'à une reprise explicite. Renvoie { taskId, active: false }. QUAND : pendant les congés, les gels, ou quand l'assigné est indisponible pour une période. EXEMPLE : pause_recurring_task taskId='j57aaaaa...'.",
	pause_task:
		"Ferme le segment de travail ouvert de la tâche et arrête le chronomètre de durée, sans terminer la tâche. En pause n'est pas bloqué : la tâche reste un travail réservable, simplement hors chronomètre jusqu'à sa reprise. Renvoie { taskId, status: 'todo' }. QUAND : avant de quitter une tâche in_progress, pour que sa durée facturée ne continue pas de s'accumuler pendant l'inactivité. EXEMPLE : pause_task taskId='b2v9k4x7p1m6q0z3w8n5r2t4y7c1u9df' callerOrchestrator='gamma'.",
	recall:
		"Recherche vectorielle sémantique dans les mémoires VantagePeers, classée par similarité cosinus. Renvoie { items[{ memoryId, score, namespace, type, content }], truncated? }, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour retrouver des décisions, règles ou faits passés par leur sens plutôt que par leurs mots exacts (text_search correspond aux termes exacts). EXEMPLE : recall query='Pi feedback rules' namespace='global' type='feedback' limit=20.",
	remove_repo_mapping:
		"Supprime l'association d'un dépôt GitHub par son nom de dépôt, ce qui arrête le routage des événements webhook pour ce dépôt. Renvoie { repo, deleted } ; deleted vaut false quand aucune association n'existait pour ce dépôt. QUAND : quand un dépôt est archivé ou que ses événements ne doivent plus générer de notifications VP. EXEMPLE : remove_repo_mapping repo='vantageos-agency/vantage-peers'.",
	resume_recurring_task:
		"Reprend un modèle de tâche récurrente en pause et recalcule l'heure de sa prochaine exécution planifiée. Renvoie { taskId, active: true, nextRunAt }. QUAND : à la fin d'une période de pause, pour réactiver la génération automatique de tâches. EXEMPLE : resume_recurring_task taskId='j57aaaaa...'.",
	resume_task:
		"Ouvre un nouveau segment de travail sur une tâche en pause et la repasse en in_progress. Renvoie { taskId, status: 'in_progress' }. QUAND : après pause_task, pour relancer le chronomètre sur la même tâche. EXEMPLE : resume_task taskId='b2v9k4x7p1m6q0z3w8n5r2t4y7c1u9df' callerOrchestrator='gamma'.",
	search_briefing_notes_by_keyword:
		"Recherche plein texte BM25 par mots-clés dans le contenu des notes de briefing, classée par pertinence. Renvoie { items[{ _id, title, topic, participants, createdBy, createdAt }], truncated? } : les notes correspondantes, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour retrouver des briefings sur un sujet ou une décision quand les filtres de list_briefing_notes sont trop grossiers, par exemple « trouver les briefings sur le plan de migration ». EXEMPLE : search_briefing_notes_by_keyword query='migration plan' topic='daily' limit=10.",
	search_episodes_by_keyword:
		"Recherche plein texte BM25 par mots-clés limitée aux épisodes (mémoires de type='episode'). Renvoie { items[{ memoryId, namespace, type, content }], truncated? } : les épisodes correspondants, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : quand search_episodes_by_semantic renvoie des résultats trop larges et que vous avez besoin d'une expression exacte ou d'un ID dans un champ d'épisode. EXEMPLE : search_episodes_by_keyword query='convex deploy schema' namespace='orchestrator/sigma' limit=10.",
	search_episodes_by_semantic:
		"Recherche vectorielle sémantique limitée aux épisodes (mémoires de type='episode'), classée par similarité cosinus. Renvoie { items[{ memoryId, score, namespace, type, content }], truncated? }, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour retrouver des événements passés structurés par intention : modes de défaillance, leçons, contextes similaires. EXEMPLE : search_episodes_by_semantic query='hook false positive blocked publish' namespace='orchestrator/sigma' limit=20.",
	search_fix_patterns:
		"Recherche sémantique dans les fix patterns par description de symptôme, classée par pertinence. Renvoie { items[{ patternId, score, symptom, rootCause, validatedFix?, tags, stack, sourceProject, severity }], truncated? }, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : AVANT de corriger tout bug, pour vérifier si un pattern correspondant existe et réutiliser la correction validée. EXEMPLE : search_fix_patterns query='message disappears after sending on mobile' limit=5.",
	search_messages_by_keyword:
		"Recherche plein texte BM25 par mots-clés dans le contenu des messages, classée par pertinence. Renvoie { items[{ _id, from, content, createdAt, channel }], truncated? } : les messages correspondants, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour un audit post-incident ou pour retrouver des messages directs entre pairs par sujet, par exemple « trouver les messages sur le déploiement » dans la fenêtre sessionDay récente. EXEMPLE : search_messages_by_keyword query='convex deploy' from='pi' sessionDay=102 limit=10.",
	search_tasks_by_keyword:
		"Recherche plein texte BM25 par mots-clés dans les titres de tâches, classée par pertinence. Renvoie { items[{ _id, title, assignedTo, priority, status }], truncated? } : les tâches correspondantes, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : pour trouver des tâches par sujet ou mot-clé quand les filtres de list_tasks sont trop larges, par exemple « trouver les tâches sur les hooks » parmi tous les assignés. EXEMPLE : search_tasks_by_keyword query='hook PostToolUse' status='todo' limit=10.",
	send_message:
		"Envoie un message à un ou plusieurs agents PAR ID D'AGENT (recipientAgentIds, les valeurs `agentId` que renvoie list_peers), ou par routage de canal (broadcast / rôle de flotte / instance). Renvoie { messageId, from, recipientAgentIds?, channel?, stateUnverified? } : recipientAgentIds ou channel, tel que l'appel l'a adressé, et stateUnverified (les affirmations d'état du contenu que le serveur n'a pas pu vérifier) quand il y en a ; conservez messageId pour list_broadcast_status. QUAND : pour prévenir des pairs d'une tâche terminée, d'une passation ou d'une décision ; crée un accusé de réception par destinataire. Passez exactement l'un de recipientAgentIds et channel ; un agent de votre organisation est adressé par son ID, un nom n'est jamais comparé à un ID. EXEMPLE : send_message from='agent-a' recipientAgentIds=['<agentId from list_peers>'] content='Brief ready'. EXEMPLE : send_message from='alpha' channel='beta' content='C3 descriptions PR ready for review'.",
	set_summary:
		"Définit le résumé de statut d'une instance d'orchestrateur : une ou deux phrases sur ce sur quoi elle travaille maintenant, qui remplacent le résumé précédent et que les pairs lisent dans list_peers. Renvoie { orchestratorId, instanceId, summary }. QUAND : en début de session et après un changement majeur de priorité, pour que les pairs voient ce que vous faites. EXEMPLE : set_summary orchestratorId='alpha' instanceId='alpha-vps' summary='Standardizing 86 tool descriptions for B2'.",
	soft_delete_document:
		"Supprime logiquement tous les fragments de base de connaissances d'un document. Marque chaque fragment isLatest=true de docId comme isLatest=false : les fragments restent en base pour l'audit mais sont exclus de recall et de la recherche. Exige un JWT Clerk avec org_id (la même organisation que celle qui a ingéré le document). Un document par appel. Renvoie { docId, markedCount } : docId est le document supprimé logiquement, markedCount compte les fragments marqués supprimés dans le premier lot de cet appel ; un document plus grand se termine en arrière-plan, donc un compteur égal à la taille du lot signifie que d'autres étaient encore en cours de marquage (0 quand aucun n'était actif, par exemple lors d'un appel répété). EXEMPLE : soft_delete_document docId='abc-123-uuid'.",
	soft_delete_memory:
		"Supprime logiquement une mémoire pour qu'elle n'apparaisse plus dans les résultats de recall, tout en restant dans le journal d'audit. Renvoie { deleted: true, memoryId }. QUAND : pour retirer un fait obsolète ou une règle remplacée sans perte définitive de données. EXEMPLE : soft_delete_memory memoryId='j57dy3049btafda9m2f5d2ggk987ph3f'.",
	start_task:
		"Passe une tâche en in_progress et enregistre l'horodatage startedAt pour le suivi de durée. Renvoie { taskId, status: 'in_progress' }. QUAND : comme première action en prenant une tâche, pour signaler l'activité et activer les métriques. EXEMPLE : start_task taskId='k178d3ns...' callerOrchestrator='gamma'.",
	store_document_chunked:
		"Ingère un document binaire (PDF, Markdown, texte brut) dans la base de connaissances. storageId désigne un fichier déjà téléversé et réservé pour votre organisation : generate_upload_url (avec le sha256 du fichier) renvoie l'URL de téléversement et le ticket, le fichier y est envoyé par POST, et claim_upload (avec le ticket) renvoie le storageId que prend cet outil. Un storageId que votre organisation n'a pas réservé est refusé (AUTH_STORAGE_NOT_OWNED). Côté serveur : extraction du texte → découpage tenant compte des paragraphes (~512 tokens par fragment avec un chevauchement de 50 caractères) → stockage des fragments comme mémoires dans le namespace team/<orgId>/<docId>. Exige un JWT Clerk avec org_id ; les porteurs sans organisation sont rejetés. Réingérer avec le même docId remplace la version précédente (bascule isLatest, idempotent). Un document par appel. Renvoie { docId, chunkCount, storageId }. EXEMPLE : store_document_chunked storageId='kg2anjqa…' mimeType='text/markdown' filename='spec.md'.",
	store_episode:
		"Stocke une mémoire épisodique structurée qui capture le contexte, l'objectif, l'action, le résultat et l'enseignement d'un événement passé. Omettez namespace pour écrire dans votre propre espace. Renvoie { memoryId, type: 'episode', severity, namespace, createdBy } ; le memoryId est l'episodeId que prend get_episode. QUAND : après avoir terminé une tâche non triviale ou rencontré un échec ou un succès inattendu. EXEMPLE : store_episode namespace='orchestrator/alpha' createdBy='alpha' severity='major' context='...' goal='...' action='...' outcome='...' insight='...'.",
	store_memory:
		"Stocke une entrée de mémoire typée dans VantagePeers, éventuellement liée à une mémoire antérieure. Omettez namespace pour écrire dans votre propre espace. Renvoie { memoryId, namespace, type, content, createdBy } ; conservez memoryId pour get_memory ou soft_delete_memory. QUAND : après toute décision, règle ou leçon qui doit persister d'une session à l'autre. EXEMPLE : store_memory type='feedback' content='Alpha prefers concise replies' (sans namespace : écrite dans votre propre espace).",
	text_search:
		"Recherche plein texte BM25 par mots-clés dans les mémoires VantagePeers, pour une correspondance de termes exacts. Renvoie { items[{ memoryId, namespace, type, content }], truncated? }, la meilleure correspondance en premier ; le texte est la même liste d'éléments en tableau JSON nu ; au-delà du plafond de réponse de 60 Ko, les deux sont coupés et le signalent (truncated: true, et _meta dans le texte). QUAND : les mots ou l'ID à trouver sont connus exactement (recall classe plutôt par le sens). EXEMPLE : text_search query='Day 92 C3 descriptions' namespace='project/vantage-peers' limit=10.",
	update_briefing_note:
		"Met à jour une note de briefing existante ; seuls les champs fournis sont modifiés (les tableaux sont REMPLACÉS EN ENTIER). Renvoie { noteId, updated: true }. QUAND : pour ajouter des décisions, corriger le contenu ou relier à nouveau des mémoires ; RBAC : l'appelant doit être createdBy ou system. EXEMPLE : update_briefing_note noteId='j57aaaaa...' callerOrchestrator='alpha' decisions=['Use hybrid_search first'].",
	update_mission:
		"Met à jour n'importe quel champ modifiable d'une mission. Chaque champ donné écrase la valeur stockée (agents est remplacé en entier, jamais complété) ; les champs omis sont conservés et updatedAt est défini. Annuler (status='cancelled') exige callerOrchestrator, le créateur de la mission ou 'system', et un cancelReason ; une mission complete ne peut pas être annulée. Renvoie { missionId, updated: true }. QUAND : pour faire avancer le statut, mettre à jour le pourcentage d'avancement, ou changer le pilote ou les agents en cours de route. EXEMPLE : update_mission missionId='k57a36y8...' progress=75 status='validate'.",
	update_mission_status:
		"Change le statut de cycle de vie d'une mission en un seul appel, sans toucher aux autres champs. Servi au fleet master uniquement : tout autre appelant est refusé. Renvoie { missionId, status }. QUAND : seul le statut change ; update_mission modifie les autres champs et enregistre un cancelReason. EXEMPLE : update_mission_status missionId='k57a36y8...' status='complete'.",
	update_mission_template:
		"Crée ou met à jour (upsert) un modèle de mission par son nom ; les modèles existants sont écrasés. Fleet master uniquement (le catalogue est partagé dans toute la flotte). Les étapes et la description sont remplacées en entier (une description omise est effacée) ; un brief ou un isDefault omis conserve la valeur stockée. Les missions déjà instanciées ne sont pas modifiées. Renvoie { templateId, name, stepCount }. QUAND : pour définir ou affiner des plans de flux de travail réutilisables en plusieurs étapes pour des types de missions récurrents. EXEMPLE : update_mission_template name='issue-resolution-v2' steps=[{title:'Triage',description:'...'}] createdBy='alpha'.",
	update_profile:
		"Crée ou met à jour le profil d'un orchestrateur, avec des faits d'identité statiques et un état de session dynamique. N'écrit que le propre profil de l'agent appelant (le fleet master peut écrire n'importe lequel) ; les champs donnés remplacent ceux stockés, les champs omis sont conservés. Renvoie { profileId, orchestratorId, name }. QUAND : à chaque début de session pour mettre à jour lastSeen/sessionCount, ou quand le rôle ou les capacités changent. EXEMPLE : update_profile orchestratorId='alpha' dynamic={lastSeen: Date.now(), sessionCount: 5}.",
	update_recurring_task:
		"Met à jour les champs d'un modèle de tâche récurrente ; un changement de cronExpression recalcule automatiquement nextRunAt. Renvoie { recurringTaskId, updated: true }. QUAND : pour changer l'assigné, la planification ou la priorité d'un modèle récurrent actif. EXEMPLE : update_recurring_task recurringTaskId='j57aaaaa...' cronExpression='0 10 * * 1' priority='high'.",
	update_task:
		"Met à jour n'importe quel champ modifiable d'une tâche ; seuls les champs fournis sont modifiés, updatedAt est défini automatiquement. Renvoie { taskId, updated: true }. QUAND : pour réassigner, changer la priorité ou ajouter du contexte à une tâche existante sans la recréer. EXEMPLE : update_task taskId='k178d3ns...' status='review' callerOrchestrator='alpha'. NOTE : sur une tâche [REVIEW], l'orchestrateur qui l'a réassignée ailleurs le plus récemment (lastAssignedTo) peut la reprendre en remettant assignedTo à lui-même.",
	validate_fix:
		"Définit ou met à jour la description de la correction validée d'un fix pattern, après avoir confirmé qu'elle fonctionne. Fleet master uniquement. Écrase le validatedFix du pattern avec le texte donné (la valeur précédente n'est pas conservée) et réindexe le pattern pour search_fix_patterns. Renvoie { patternId, validatedFix, validated: true }. QUAND : après une tentative de correction réussie, pour la promouvoir comme solution de référence du pattern. EXEMPLE : validate_fix patternId='j57aaaaa...' validatedFix='Add suppressHydrationWarning to date elements'.",
	whoami:
		"Indique au nom de qui cette connexion agit et ce qu'elle peut lire et écrire, lu uniquement à partir de son propre identifiant. Renvoie { agent_id, agent_name, agent_status, org_slug, role, suggested_orchestrator_id, acting_name, default_write_namespace, writableNamespaces, namespaceReadPrefixes, namespaceWritePrefixes, fromAllowList, scope_profile_name, actor, caller_id, agent_unresolved_reason } : agent_id est l'ID permanent que les outils prennent comme ID d'agent, suggested_orchestrator_id le nom à passer là où un outil demande quel orchestrateur agit, default_write_namespace l'endroit où une écriture aboutit quand aucun namespace n'est donné. QUAND : quand un appel a besoin de votre ID d'agent, de votre nom d'orchestrateur ou de vos namespaces, au lieu de les demander à l'utilisateur. EXEMPLE : whoami (sans arguments).",
	write_diary:
		"Écrit ou met à jour (upsert) une entrée de journal pour une date et un orchestrateur donnés, avec ses points marquants et ses blocages. Renvoie { diaryId, date, orchestrator } ; réécrire la même date remplace le contenu, les points marquants et les blocages de cette entrée. QUAND : en fin de session, pour consigner ce qui a été accompli, appris, et ce qui a bloqué l'avancement. EXEMPLE : write_diary date='2026-06-06' orchestrator='gamma' content='Standardized 86 descriptions...'.",
};

/**
 * The description a tool serves: "<English> / <French>" when the tool has a
 * French entry and the joined text fits METADATA_FIELD_BUDGET_BYTES, else the
 * English exactly as given. `english` is the full English text, person-door
 * note included; `noPersonDoor` says whether it carries that note, so the
 * French half carries its counterpart in the same place.
 */
export function composeServedDescription(
	name: string,
	english: string,
	noPersonDoor: boolean,
): string {
	if (!Object.hasOwn(TOOL_DESCRIPTIONS_FR, name)) return english;
	const french = `${TOOL_DESCRIPTIONS_FR[name]}${noPersonDoor ? NO_PERSON_DOOR_NOTE_FR : ""}`;
	const bilingual = `${english}${BILINGUAL_SEPARATOR}${french}`;
	return Buffer.byteLength(bilingual, "utf8") <= METADATA_FIELD_BUDGET_BYTES
		? bilingual
		: english;
}
